import React, { useState, useContext } from "react";
import { TextField, Button, Container, Typography, Box, Snackbar, CircularProgress, Alert } from "@mui/material";
import { useNavigate } from "react-router-dom";
import { collection, getDocs, query, where } from "firebase/firestore";
import { db ,updateDoc,doc} from "../firebase/firebaseConfig"; // Ensure Firebase is correctly imported
import { AuthContext } from "../context/AuthContext";
import { v4 as uuidv4 } from "uuid";
import "../css/Login.css";

const Login = () => {
  const [credentials, setCredentials] = useState({ username: "", password: "" });
  const [loading, setLoading] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: "", severity: "success" });

  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleChange = (e) => {
    setCredentials({ ...credentials, [e.target.name]: e.target.value });
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const usersRef = collection(db, "users");
      const q = query(usersRef, where("userName", "==", credentials.username), where("password", "==", credentials.password));
      const querySnapshot = await getDocs(q);

      if (!querySnapshot.empty) {
        const userDoc = querySnapshot.docs[0];
        const userData = userDoc.data();
        const token = uuidv4();
        
        // Update token in Firestore
         updateDoc(doc(db, "users", userDoc.id), { token });

        const authUser = { uid: userDoc.id, userName: userData.userName,role:userData.roleID, token };
        
        login(authUser);
        setSnackbar({ open: true, message: "Login successful!", severity: "success" });

        // setTimeout(() => navigate("/home"), 500);
      } else {
        setSnackbar({ open: true, message: "Invalid credentials", severity: "error" });
      }
    } catch (error) {
      console.error("Error fetching user:", error);
      setSnackbar({ open: true, message: "Login failed. Please try again.", severity: "error" });
    }
    setLoading(false);
  };

  return (
    <Container maxWidth="sm" sx={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center",width:'100%' }}>
      <Typography
        variant="h4"
        className="login-title"
        sx={{
          fontWeight: "bold",
          mt:2,
          mb: 3,
          textAlign: "center",
          borderBottom: 2,
          borderColor: "#3f51b5",
          color:'#3f51b5',
          fontSize: { xs: "1.8rem", sm: "2.5rem" },
          paddingBottom: 1,
        }}
      >
        RSO Canteen Service
      </Typography>

      <Box
        sx={{
          width: "100%",
          maxWidth: 400,
          p: 4,
          boxShadow: 3,
          borderRadius: 2,
          textAlign: "center",
          bgcolor: "background.paper",
        }}
      >
        <Typography variant="h5" className="login-title" sx={{ textAlign: "left", color:'#3f51b5',textDecoration:'underline', fontWeight: "700", mb: 3, fontSize: { xs: "1.8rem", sm: "1.5rem" } }} gutterBottom>
          Login
        </Typography>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
          <TextField fullWidth label="Username" name="username" variant="outlined" value={credentials.username} onChange={handleChange} required />
          <TextField fullWidth label="Password" name="password" type="password" variant="outlined" value={credentials.password} onChange={handleChange} required />
          
          <Button type="submit" variant="contained" color="primary" fullWidth sx={{ py: 1.2, fontSize: "1rem", position: "relative" }} disabled={loading}>
            {loading ? <CircularProgress size={24} sx={{ color: "white" }} /> : "Login"}
          </Button>
        </form>
      </Box>

      {/* Snackbar Notification */}
      <Snackbar open={snackbar.open} autoHideDuration={3000} onClose={handleCloseSnackbar} anchorOrigin={{ vertical: "top", horizontal: "center" }}>
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: "100%" }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default Login;
