import React, { useState, useEffect, useContext } from "react";
import {
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  CircularProgress,
  TablePagination,
  Snackbar,
  Dialog, DialogTitle, DialogContent, DialogContentText, DialogActions, Tooltip,
  
  Alert,
} from "@mui/material";


import { Check, DoneAll, Cancel } from "@mui/icons-material";
import { useParams } from "react-router-dom";
import { db, collection, query, where, getDocs, updateDoc, doc ,setDoc,orderBy,getDoc,onSnapshot} from "../firebase/firebaseConfig";
import dayjs from "dayjs";
import { Timestamp } from "firebase/firestore";

export default function OrderPage() {

  const { category } = useParams();
  const [orders, setOrders] = useState([]);
  const [open, setOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [updating, setUpdating] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: "", severity: "success" });
  const [openConfirmDialog, setOpenConfirmDialog] = useState(false);
  const [pendingUpdate, setPendingUpdate] = useState(null);
  const handleOpen = (order, item) => {
    setSelectedItem({ ...item, userName: order.userName, orderId: order.id ,remark:order.Remarks});
    // //console.log(order)
    setOpen(true);
  };
  useEffect(() => {
    setPage(0); // Reset pagination when category changes
  }, [category, orders]); 
  
  const handleClose = () => {
    setOpen(false);
    setSelectedItem(null);
  };
  useEffect(() => {
    const todayStart = Timestamp.fromDate(dayjs().startOf('day').toDate());
    const todayEnd = Timestamp.fromDate(dayjs().endOf('day').toDate());
  
    const q = query(
      collection(db, 'orders'),
      where('timestamp', '>=', todayStart),
      where('timestamp', '<=', todayEnd),
      orderBy('timestamp', 'desc')
    );
  
    const unsubscribe = onSnapshot(q, (snapshot) => {
      let ordersData = snapshot.docs.map((doc) => ({
        id: doc.id,
        ...doc.data(),
      }));
  
      // Flatten the orderItems and add orderId to each item
      const flattenedOrders = ordersData.flatMap((order) => {
        return order.orderItems.map((item) => ({
          orderId: order.id,  // Add orderId to each item
          ...item,
          userName: order.userName,
          timestamp: order.timestamp,
        }));
      });
  
      const filteredOrders = flattenedOrders
        .filter((item) => item.catName === category) // Filter based on category
        .sort((a, b) => {
          const order = [1, 0, 3, 2]; // Define sorting order
          const statusCodeSort = order.indexOf(a.statusCode) - order.indexOf(b.statusCode);
          if (statusCodeSort !== 0) {
            return statusCodeSort; // Sort by statusCode
          }
          return b.timestamp.seconds - a.timestamp.seconds; // Sort by timestamp
        });
        // console.log(filteredOrders)
      setOrders(filteredOrders);
      setLoading(false);
    });
  
    return () => unsubscribe();
  }, [category]);
  

  
  
  const handleConfirmUpdate = async () => {
    if (pendingUpdate) {
     // console.log(pendingUpdate)
     setOpenConfirmDialog(false);
     setPendingUpdate(null);
      await updateOrderItemStatusConfirmed(
        pendingUpdate.orderId,
        pendingUpdate.itemId,
        pendingUpdate.newStatus
      );
    }

  };
  
  const handleCancelUpdate = () => {
    setOpenConfirmDialog(false);
    setPendingUpdate(null);
  };
  
  const updateOrderItemStatus = async (orderId,  itemId, newStatus) => {
    if (newStatus === 2) {
      setPendingUpdate({ orderId,  itemId, newStatus });
      
      // console.log(orderId,  itemId, newStatus)
      setOpenConfirmDialog(true);
      return;
    }
    await updateOrderItemStatusConfirmed(orderId,  itemId, newStatus);
  };
  
  const updateOrderItemStatusConfirmed = async (orderId,  itemId, newStatus) => {
    // console.log(orderId,itemId,newStatus)
    try {
      setLoading(true);

      const orderRef = doc(db, "orders", orderId);
      const orderSnap = await getDoc(orderRef);

      if (!orderSnap.exists()) {
        console.error("Order not found");
        return;
      }

      const orderData = orderSnap.data();
      const updatedOrderItems = orderData.orderItems.map((item) =>
        item.itemId === itemId ? { ...item, statusCode: newStatus } : item
      );

      const userDetails = JSON.parse(localStorage.getItem("authUser"));

      await updateDoc(orderRef, {
        orderItems: updatedOrderItems,
        updatedBy: userDetails.userName,
        updatedAt: Timestamp.now(),
      });

      if (newStatus === 2 || newStatus === 3) {
        const userQuery = query(collection(db, "users"), where("employeeCode", "==", orderData.employeeCode));
        const userSnapshot = await getDocs(userQuery);

        if (userSnapshot.empty) {
          const userRef = doc(collection(db, "users"));
          await setDoc(userRef, {
            userName: orderData.userName,
            employeeCode: orderData.employeeCode,
          });
          ////console.log("User created");
        } else {
          //console.log("User found");
          userSnapshot.forEach((doc) => doc.data());
        }
      }

      setSnackbar({ open: true, message: "Order status updated successfully!", severity: "success" });
    } catch (error) {
      console.error("Error updating order item status:", error);
      setSnackbar({ open: true, message: "Failed to update order status!", severity: "error" });
    } finally {
      setLoading(false);
    }
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0); // Reset to first page when rows per page changes
  };
  
  return (
    <div style={{ padding: "1px", position: "relative" }}>
    <Typography
      variant="h5"
      sx={{
        textAlign: "center",
        mt:2.5,
        fontWeight: "bold",
        textTransform: "capitalize",
        marginBottom: 2,
        color:'#3f51b5',
        
      }}
    >
      {category} Orders
    </Typography>
  
    {loading ? (
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "300px" }}>
        <CircularProgress />
      </div>
    ) : (
<TableContainer component={Paper} sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', width: '100%', overflowX: 'auto', paddingRight: '1px', paddingLeft: '0px' }}>
  <Table>
    <TableHead>
      <TableRow sx={{ backgroundColor: '#f5f5f5', height: '50px' }}>
        {['Employee Name', 'Order Item', 'Qty.', 'Status'].map((header) => (
          <TableCell key={header} sx={{ fontWeight: '500', fontSize: '1rem', padding: '5px', backgroundColor: '#3f51b5', color: 'black' }}>
            {header}
          </TableCell>
        ))}
      </TableRow>
    </TableHead>
    <TableBody>
      {orders.length === 0 ? (
        <TableRow sx={{ height: '50px' }}>
          <TableCell colSpan={4} align="center" sx={{ py: 2 }}>
            No orders found
          </TableCell>
        </TableRow>
      ) : (
        orders.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((item, index) => (
          <TableRow key={`${item.orderId}-${index}`} sx={{ height: '50px' }}>
            <TableCell sx={{
              fontWeight: 'bold',
              textTransform: 'capitalize',
              fontSize: '0.9rem',
              verticalAlign: 'middle',
              padding: '8px',
              borderRight: '1px solid #3f51b5',
              maxWidth: 110,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }}>
              <Tooltip title={item.userName} disableHoverListener={item.userName.length <= 20}>
                <Typography noWrap>{item.userName}</Typography>
              </Tooltip>
            </TableCell>

            <TableCell sx={{
              cursor: 'pointer',
              fontSize: '0.4rem',
              verticalAlign: 'middle',
              padding: '6px',
              borderRight: '1px solid #3f51b5',
              maxWidth: 80,
              whiteSpace: 'nowrap',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
            }} onClick={() => handleOpen(item.orderId, item)}>
              <Tooltip title={item.itemName} disableHoverListener={item.itemName.length <= 20}>
                <Typography noWrap>{item.itemName}</Typography>
              </Tooltip>
            </TableCell>

            <TableCell sx={{ fontSize: '1.2rem', verticalAlign: 'middle', padding: '4px', borderRight: '1px solid #3f51b5' }}>
              {item.quantity}
            </TableCell>

            <TableCell sx={{
              padding: '6px',
              display: 'flex',
              alignItems: 'center',
              gap: '3px',
              borderRight: '1px solid #3f51b5',
            }}>
              {item.statusCode === 0 && (
                <Button onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 1)} disabled={updating}>
                  <Check color="success" sx={{ fontSize: '2.4rem' }} />
                </Button>
              )}
              {item.statusCode === 1 && (
                <Button onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 3)} disabled={updating}>
                  <DoneAll color="success" sx={{ fontSize: '2.4rem' }} />
                </Button>
              )}
              {item.statusCode !== 2 && item.statusCode !== 3 && (
                <Button sx={{ padding: '6px 0px', minWidth: '50px' }} onClick={() => updateOrderItemStatus(item.orderId, item.itemId, 2)} disabled={updating}>
                  <Cancel color="error" sx={{ fontSize: '1rem' }} />
                </Button>
              )}
              {item.statusCode === 2 && (
                <Button disabled style={{ color: 'red', fontWeight: '800', fontSize: '0.8rem', margin: 0, padding: '10px' }}>
                  Cancelled
                </Button>
              )}
              {item.statusCode === 3 && (
                <Button disabled style={{ color: 'green', fontWeight: '800', fontSize: '0.8rem', margin: 0, padding: '10px' }}>
                  Delivered
                </Button>
              )}
            </TableCell>
          </TableRow>
        ))
      )}
    </TableBody>
  </Table>
</TableContainer>

    )}

<TablePagination
  rowsPerPageOptions={[10, 25]}
  component="div"
  count={orders.length} // Total number of flattened items
  rowsPerPage={rowsPerPage}
  page={page}
  onPageChange={handleChangePage}
  onRowsPerPageChange={handleChangeRowsPerPage}
/>


    <Snackbar open={snackbar.open} autoHideDuration={3000} onClose={() => setSnackbar({ ...snackbar, open: false })}>
      <Alert severity={snackbar.severity}>{snackbar.message}</Alert>
    </Snackbar>
  
    <Dialog open={openConfirmDialog} onClose={handleCancelUpdate}>
      <DialogTitle>Confirm Order Status Update</DialogTitle>
      <DialogContent>
        <DialogContentText>Are you sure?</DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleConfirmUpdate} color="primary">
          Yes
        </Button>
        <Button onClick={handleCancelUpdate} color="secondary">
          No
        </Button>
      </DialogActions>
    </Dialog>
  
    <Dialog open={open} onClose={handleClose}>
      <DialogTitle sx={{padding:1,margin:'15px'}}> Order Item Details</DialogTitle>
      <DialogContent>
        {selectedItem && (
          <>
            <Typography>
              <strong>Employee Name:</strong> {selectedItem.userName}
            </Typography>
            <Typography>
              <strong>Item Name:</strong> {selectedItem.itemName}
            </Typography>
            <Typography>
              <strong>Item Description:</strong> {selectedItem.itemDesc}
            </Typography>
            <Typography>
              <strong>Remark:</strong> {selectedItem.remark}
            </Typography>
            <Typography>
              <strong>Quantity:</strong> {selectedItem.quantity}
            </Typography>
          </>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose} color="primary">
          Close
        </Button>
      </DialogActions>
    </Dialog>
  </div>
  
  );
}
