import React, { useState, useEffect } from "react";
import {
  Box,
  Grid,
  Button,
  Container,
  Paper,
  TextField,
  Typography,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  IconButton,
  CircularProgress,
  Snackbar,
  Alert,
} from "@mui/material";
import { db, collection, addDoc, getDocs, query, orderBy } from "../firebase/firebaseConfig";
import DeleteIcon from "@mui/icons-material/Delete";
import "../css/AddItem.css";  // Importing the CSS for responsiveness
import { Timestamp } from "firebase/firestore";

const AddItem = ({ onBack }) => {
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(false); // Spinner state
  const [snackbarOpen, setSnackbarOpen] = useState(false); // Snackbar state
  const [formError, setFormError] = useState(""); // Error message for validation
  const [errorFields, setErrorFields] = useState([]); // Array to store invalid field indices

  useEffect(() => {
    const fetchCategories = async () => {
      const categoriesRef = collection(db, "menuitemscategory");
      const q = query(categoriesRef, orderBy("catName", "asc"));
      const querySnapshot = await getDocs(q);

      const categoriesList = querySnapshot.docs.map((doc) => ({
        catID: doc.data().catID,
        catName: doc.data().catName,
      }));

      setCategories(categoriesList);
    };

    fetchCategories();
  }, []);

  const generateItemId = () => Math.floor(10000 + Math.random() * 90000);

  const [items, setItems] = useState([
    {
      id: generateItemId(),
      itemName: "",
      itemDescription: "",
      price: "",
      categoryId: "",
      day: "",
      available: true,
    },
  ]);

  const handleItemChange = (index, field, value) => {
    const newItems = [...items];
    newItems[index][field] = value;
    setItems(newItems);
  };

  const addNewItem = () => {
    setItems([
      ...items,
      {
        id: generateItemId(),
        itemName: "",
        itemDescription: "",
        price: "",
        categoryId: "",
        day: "",
        available: true,
      },
    ]);
  };

  const removeItem = (index) => {
    const newItems = items.filter((_, i) => i !== index);
    setItems(newItems);
  };

  const validateForm = () => {
    const invalidFields = [];

    items.forEach((item, index) => {
      if (
        !item.itemName ||
        !item.itemDescription ||
        !item.price ||
        !item.categoryId ||  // Check if categoryId is empty or invalid
        !item.day
      ) {
        invalidFields.push(index);
      }
    });

    if (invalidFields.length > 0) {
      setErrorFields(invalidFields);
      setFormError("All fields must be filled before submitting.");
      return false;
    }

    setErrorFields([]);
    setFormError("");
    return true;
  };


  const handleSubmit = async () => {
    if (!validateForm()) return;
    const userDetails = JSON.parse(localStorage.getItem("authUser"));

    setLoading(true);
    try {
      for (const item of items) {
        const selectedCategory = categories.find((cat) => cat.catID === item.categoryId);
        const newItem = {
          itemId: item.id,
          itemName: item.itemName,
          itemDesc: item.itemDescription,
          price: parseFloat(item.price),
          catName: selectedCategory?.catName || "",
          catID: item.categoryId || "",
          day: parseInt(item.day),
          available: item.available,
          createdAt:Timestamp.now(),
          creatdBy:userDetails.userName
        };
        // console.log(newItem);
        await addDoc(collection(db, "menuitems"), newItem);
      }

      setSnackbarOpen(true);
      setItems([{
        id: generateItemId(),
        itemName: "",
        itemDescription: "",
        price: "",
        categoryId: "",
        day: "",
        available: true,
      }]);
    } catch (error) {
      console.error("Error adding items:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container
      sx={{
        maxWidth: {
          xs: '100%',
          sm: '600px',
          md: '800px',
          lg: '1000px',
        }
        , mt: 2, mb: 1
      }}
      className="container"
    >
      <Paper elevation={3} sx={{ p: 1, mt: 0, borderRadius: 2, color: '#3f51b5' }} className="paper">
        <Typography variant="h5" gutterBottom>
          Add Multiple Items
        </Typography>

        {items.map((item, index) => (
          <Paper key={item.id} sx={{ p: 2, mb: 2, borderRadius: 2, position: "relative" }}>
            <Grid container spacing={2}>
              {/* Item Name */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Item Name"
                  margin="normal"
                  value={item.itemName}
                  onChange={(e) => handleItemChange(index, "itemName", e.target.value)}
                  error={errorFields.includes(index) && !item.itemName}
                  className="textField"
                />
              </Grid>

              {/* Item Description */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  multiline // Use multiline for multiple rows
                  rows={2}
                  label="Item Description"
                  margin="normal"
                  value={item.itemDescription}
                  onChange={(e) => handleItemChange(index, "itemDescription", e.target.value)}
                  error={errorFields.includes(index) && !item.itemDescription}
                  helperText={errorFields.includes(index) && !item.itemDescription ? "Item Description is required" : ""} // Helper text for error
                  className="textField"
                />
              </Grid>

              {/* Price */}
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Price"
                  type="number"
                  margin="normal"
                  value={item.price}
                  onChange={(e) => handleItemChange(index, "price", e.target.value)}
                  error={errorFields.includes(index) && !item.price}
                  className="textField"
                />
              </Grid>

              {/* Category */}
              <Grid item xs={12} sm={6}>
                <FormControl
                  fullWidth
                  margin="normal"
                  className="formControl"
                  error={errorFields.includes(index) && !item.categoryId}
                >
                  <InputLabel>Category</InputLabel>
                  <Select
                    value={item.categoryId || ""}  // Ensure a valid number or empty string
                    onChange={(e) => handleItemChange(index, "categoryId", Number(e.target.value))} // Convert to number
                    label="Category"
                  >
                    {categories.map((cat) => (
                      <MenuItem key={cat.catID} value={cat.catID}>
                        {cat.catName}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>

              </Grid>

              {/* Day */}
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth margin="normal" className="formControl" error={errorFields.includes(index) && !item.day}>
                  <InputLabel>Day</InputLabel>
                  <Select
                    value={item.day}
                    onChange={(e) => handleItemChange(index, "day", e.target.value)}
                    label="Day"
                  > <MenuItem value="0">All Time Available</MenuItem>
                    <MenuItem value="1">Monday</MenuItem>
                    <MenuItem value="2">Tuesday</MenuItem>
                    <MenuItem value="3">Wednesday</MenuItem>
                    <MenuItem value="4">Thursday</MenuItem>
                    <MenuItem value="5">Friday</MenuItem>
                    <MenuItem value="6">Saturday</MenuItem>

                  </Select>
                </FormControl>
              </Grid>

              {/* Available */}
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth margin="normal" className="formControl">
                  <InputLabel>Available</InputLabel>
                  <Select
                    value={item.available.toString()}
                    onChange={(e) => handleItemChange(index, "available", e.target.value === "true")}
                    label="Available"
                  >
                    <MenuItem value="true">Yes</MenuItem>
                    <MenuItem value="false">No</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
            </Grid>

            {/* Delete Button */}
            {items.length > 1 && (
              <IconButton
                onClick={() => removeItem(index)}
                sx={{ position: "absolute", top: 0, right: 10 }}
              >
                <DeleteIcon color="error" />
              </IconButton>
            )}
          </Paper>
        ))}

        {formError && (
          <Typography variant="body2" color="error" sx={{ mb: 2, fontWeight: 700 }}>
            {formError}
          </Typography>
        )}

        {/* Add More Items Button */}
        <Box sx={{ textAlign: "center", mt: 2 }}>
          <Button variant="outlined" color="primary" onClick={addNewItem} disabled={loading}>
            Add More Items
          </Button>
        </Box>

        {/* Submit and Back Buttons */}
        <Box sx={{ textAlign: "right", mt: 3 }}>
          <Button
            variant="contained"
            color="primary"
            onClick={handleSubmit}
            disabled={loading}
            className="submitButton"
          >
            {loading ? <CircularProgress size={24} /> : "Submit All Items"}
          </Button>
        </Box>
      </Paper>

      {/* Snackbar Notification */}
      <Snackbar open={snackbarOpen} autoHideDuration={3000} onClose={() => setSnackbarOpen(false)}>
        <Alert severity="success" onClose={() => setSnackbarOpen(false)}>
          Items added successfully!
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default AddItem;
