import React, { useEffect, useState } from 'react';
import {
  AppBar,
  Avatar,
  BottomNavigation,
  BottomNavigationAction,
  Box,
  Container,
  Grid,
  Toolbar,
  Typography,
  Button,
  Snackbar,
  Switch,
  Badge,
  FormControlLabel,IconButton ,useTheme,useMediaQuery
} from "@mui/material";
import {
  Coffee,
  FreeBreakfast,
  AddCircle,
  
  Fastfood,
} from "@mui/icons-material";

import RestaurantIcon from '@mui/icons-material/Restaurant';
import { Outlet, useNavigate } from "react-router-dom";
import { db, collection, query, where, onSnapshot,  doc ,writeBatch} from "../firebase/firebaseConfig";
import dayjs from "dayjs";
import { motion, AnimatePresence } from "framer-motion"; 
import { Timestamp } from "firebase/firestore";
import MuiAlert from '@mui/material/Alert'; // Import Alert
import { AuthContext } from "../context/AuthContext";
import { useContext } from "react";
import LogoutIcon from "@mui/icons-material/Logout";
import "../css/home.css";
export default function Home() {
  const { role } = useContext(AuthContext);
  const theme = useTheme();
const isSmallScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const [openModal, setOpenModal] = useState(false);
  const handleOpenModal = () => setOpenModal(true);
  const handleCloseModal = () => setOpenModal(false);
  const [footerValue, setFooterValue] = useState(0);
  const [orderCounts, setOrderCounts] = useState({
    Beverage: 0,
    Breakfast: 0,
    Lunch: 0,
    Snacks: 0,
  });
  const { user, logout } = useContext(AuthContext);
  const handleLogout = () => {
    logout();
    navigate("/"); // Redirect to login page
  };

  const [snackbarOpen, setSnackbarOpen] = useState(false);
  const [snackbarMessage, setSnackbarMessage] = useState("");
  const navigate = useNavigate();

  const [voiceNotification, setVoiceNotification] = useState(
    () => JSON.parse(localStorage.getItem("voiceNotification")) || false
  );

  // ✅ Ensure persistence in localStorage
  useEffect(() => {
    localStorage.setItem("voiceNotification", JSON.stringify(voiceNotification));
  }, [voiceNotification]);

  const Alert = React.forwardRef(function Alert(props, ref) {
    return <MuiAlert elevation={6} ref={ref} variant="filled" {...props} />;
  });

  useEffect(() => {
    const todayStart = Timestamp.fromDate(dayjs().startOf("day").toDate());
    const todayEnd = Timestamp.fromDate(dayjs().endOf("day").toDate());
  
    const q = query(
      collection(db, "orders"),
      where("timestamp", ">=", todayStart),
      where("timestamp", "<=", todayEnd)
    );
  
    const unsubscribe = onSnapshot(q, async (snapshot) => {
      const categoryCounts = { Beverage: 0, Breakfast: 0, Lunch: 0, Snacks: 0 };
      const batch = writeBatch(db);
      let showSnackbar = false;
      let snackbarMessage = "";
  
      for (const docSnap of snapshot.docs) {
        const data = docSnap.data();
        const orderId = docSnap.id;
  
        const orderItems = Array.isArray(data.orderItems) ? data.orderItems : [];
        let shouldUpdate = false;
        let itemNames = [];
  
        const updatedOrderItems = orderItems.map((item) => {
          
          if (item.statusCode === 0) {
            categoryCounts[item.catName] = (categoryCounts[item.catName] || 0) + 1;
  
            if (!data.notificationSent) {
              itemNames.push(translateItemNameToHindi(item.itemName)); // Collect all item names
              shouldUpdate = true;
            }
            
          }
          return item;
          
        });
  
        if (shouldUpdate) {
          const translatedItems = itemNames.join(", ");
          snackbarMessage = `${data.userName} ने ${translatedItems} का ऑर्डर दिया है!`;
          showSnackbar = true;
  
          batch.update(doc(db, "orders", orderId), {
            orderItems: updatedOrderItems,
            notificationSent: true,
          });
  
          // **Play voice notification only if enabled**
          if (voiceNotification) {
            announceNewOrder(data.userName, translatedItems);
          }
        }
      }
  
      await batch.commit();
      setOrderCounts(categoryCounts);
  
      if (showSnackbar) {
        setSnackbarMessage(snackbarMessage);
        setSnackbarOpen(true);
      }
    });
  
    return () => unsubscribe();
  }, [voiceNotification]);
  
  const announceNewOrder = (userName, items) => {
    const message = `${userName} ने ${items} का ऑर्डर दिया है!`; // Now supports multiple items
    const speech = new SpeechSynthesisUtterance(message);
    speech.lang = "hi-IN";
    window.speechSynthesis.speak(speech);
  };
  const translateItemNameToHindi = (itemName) => {
    // Implement your translation logic here.  This is a placeholder.
    // You could use a dictionary, a translation API, or other methods.
    // For example:
    const translations = {
      "Burger": "बर्गर",
      "Pizza": "पिज़्ज़ा",
      "Coffee": "कॉफी",
      "Tea": "चाय",
      // ... more translations
    };
    return translations[itemName] || itemName; // Return translated name or original if not found
  };




  const handleNavigate = (path) => navigate(path);

  return (
    <Container maxWidth="lg" className="home-container">
<AppBar position="fixed" sx={{ backgroundColor: "#ff996d", p: 0.5 }}>
  <Toolbar>
    <Grid container alignItems="center" justifyContent="space-between" direction={isSmallScreen ? 'column' : 'row'}>
      <Grid item sx={{ display: "flex", alignItems: "center", mb: isSmallScreen ? 1 : 0 }}>
        <Avatar src="https://raw.githubusercontent.com/Rohitastronic123/Canteen2.O/refs/heads/gh-pages/mainlogo.png" alt="IOCL Logo" sx={{ width: 55, height: 55 }} />
        <Typography variant="h6" sx={{ fontWeight: "bold", color: "#3f51b5", ml: 2 }}>
          RSO Canteen Services
        </Typography>
      </Grid>
      <Grid item sx={{ display: "flex", alignItems: "center" }}>
        <FormControlLabel
          control={
            <Switch
              checked={voiceNotification}
              onChange={() => setVoiceNotification((prev) => !prev)}
            />
          }
          label="Voice Notification"
        />
        {user && (
          <IconButton color="inherit" onClick={handleLogout}>
            <LogoutIcon />
          </IconButton>
        )}
      </Grid>
    </Grid>
  </Toolbar>
</AppBar>

      <Box sx={{ mt: 11.1, mb: 5, p: 0 ,width:'-webkit-fill-available'}}>
        <Outlet />
      </Box>

      <Snackbar open={snackbarOpen} autoHideDuration={4000} onClose={() => setSnackbarOpen(false)} message={snackbarMessage} />

      <BottomNavigation
        value={footerValue}
        onChange={(event, newValue) => setFooterValue(newValue)}
        sx={{ position: "fixed", bottom: 0, width: "100%", backgroundColor: "#fff", boxShadow: "0 -2px 5px rgba(0,0,0,0.1)" }}
      >
        <BottomNavigationAction label="Beverage" icon={<Badge badgeContent={orderCounts.Beverage} color="error" showZero><Coffee /></Badge>} onClick={() => handleNavigate("/order/Beverage")} />
        <BottomNavigationAction label="Breakfast" icon={<Badge badgeContent={orderCounts.Breakfast} color="error" showZero><FreeBreakfast /></Badge>} onClick={() => handleNavigate("/order/Breakfast")} />
        <BottomNavigationAction label="Add" icon={<AddCircle />} onClick={handleOpenModal} />
        <BottomNavigationAction label="Lunch" icon={<Badge badgeContent={orderCounts.Lunch} color="error" showZero><RestaurantIcon   /></Badge>} onClick={() => handleNavigate("/order/Lunch")} />
        <BottomNavigationAction label="Snacks" icon={<Badge badgeContent={orderCounts.Snacks} color="error" showZero><Fastfood /></Badge>} onClick={() => handleNavigate("/order/Snacks")} />
      </BottomNavigation>

      <AnimatePresence>
        {openModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="modal-backdrop" // Give it a class for styling
            onClick={handleCloseModal}
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              backgroundColor: 'rgba(0, 0, 0, 0.5)',
              display: 'flex',
              justifyContent: 'center',
              alignItems: 'center',
              zIndex: 1000, // Ensure it's on top
            }}
          >
            <motion.div
              initial={{ y: 50, opacity: 0, scale: 0.8 }}
              animate={{ y: 0, opacity: 1, scale: 1 }}
              exit={{ y: 50, opacity: 0, scale: 0.8 }}
              transition={{ duration: 0.3, ease: 'easeOut' }}
              className="modal-content"
              style={{
                backgroundColor: '#fff',
                padding: '20px',
                borderRadius: '10px',
                width: '90%', 
                maxWidth: '400px', 
                boxSizing: 'border-box', 
              }}
            >
              <Typography variant="h6" sx={{ mb: 2, textAlign: 'center' }}>
                Choose an Options
              </Typography>
              <Button
                variant="contained"
                color="primary"
                fullWidth
                sx={{ mb: 2 }}
                onClick={() => handleNavigate('/add-item')}
              >
                Add Item
              </Button>
              <Button
                variant="contained"
                color="secondary"
                fullWidth
                sx={{ mb: 2 }}
                onClick={() => handleNavigate('/view-items')}
              >
                View Items
              </Button>
              <Button
                variant="contained"
                color="success"
                fullWidth
                onClick={() => handleNavigate('/payments')}
              >
                Payments
              </Button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </Container>
  );
}
